using System;
using System.IO;
using System.Diagnostics;
using System.Security.Principal;
using System.Security.AccessControl;
using System.Text;
using Microsoft.Win32;
static class InstallSupport {
 public static string Owner = WindowsIdentity.GetCurrent().User.Value;
 public static bool Administrator { get { return new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator); } }
 public static string DefaultFolder { get { string p=Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86);if(String.IsNullOrEmpty(p))p=Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles);return Path.Combine(p,"SemperFi"); } }
 public static bool Protected(string folder) { string full=Path.GetFullPath(folder).TrimEnd('\\');foreach(var special in new[]{Environment.SpecialFolder.ProgramFiles,Environment.SpecialFolder.ProgramFilesX86,Environment.SpecialFolder.Windows}){string p=Environment.GetFolderPath(special);if(!String.IsNullOrEmpty(p)&&(full.Equals(p,StringComparison.OrdinalIgnoreCase)||full.StartsWith(p.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase)))return true;}return false; }
 public static string Quote(string value) { var b=new StringBuilder("\"");int slashes=0;foreach(char c in value){if(c=='\\'){slashes++;continue;}if(c=='\"'){b.Append('\\',slashes*2+1);b.Append(c);}else{b.Append('\\',slashes);b.Append(c);}slashes=0;}b.Append('\\',slashes*2);return b.Append('"').ToString(); }
 public static int Elevate(string exe,string args) { using(var p=Process.Start(new ProcessStartInfo(exe,args){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden})){p.WaitForExit();return p.ExitCode;} }
 public static string RegistryPath(string id) { return @"Software\Microsoft\Windows\CurrentVersion\Uninstall\SemperFi-"+id; }
 public static RegistryKey UserHive(string sid) { var identity=new SecurityIdentifier(sid);if(!identity.IsAccountSid())throw new IOException("Utilisateur d'installation invalide.");var key=Registry.Users.OpenSubKey(sid,true);if(key==null)throw new IOException("Le profil Windows de l'utilisateur n'est pas charge.");return key; }
 public static void Register(string folder,string id,string sid) { using(var hive=UserHive(sid))using(var key=hive.CreateSubKey(RegistryPath(id))){key.SetValue("DisplayName","Semper Fi");key.SetValue("DisplayVersion","0.7");key.SetValue("Publisher","Installation personnalisee Semper Fi");key.SetValue("InstallLocation",folder);key.SetValue("DisplayIcon",Path.Combine(folder,"SF.EXE")+",0");key.SetValue("UninstallString",Quote(Path.Combine(folder,"Desinstaller.exe")));key.SetValue("NoModify",1,RegistryValueKind.DWord);key.SetValue("NoRepair",1,RegistryValueKind.DWord);key.SetValue("InstallDate",DateTime.Today.ToString("yyyyMMdd"));long bytes=0;foreach(string file in Directory.GetFiles(folder,"*",SearchOption.AllDirectories))bytes+=new FileInfo(file).Length;key.SetValue("EstimatedSize",(int)Math.Min(Int32.MaxValue,(bytes+1023)/1024),RegistryValueKind.DWord);} }
 public static void Unregister(string folder,string id,string sid) { using(var hive=UserHive(sid)){using(var key=hive.OpenSubKey(RegistryPath(id))){if(key==null)return;if(!String.Equals(key.GetValue("InstallLocation") as string,folder,StringComparison.OrdinalIgnoreCase))throw new IOException("Entree Windows appartenant a une autre installation.");}hive.DeleteSubKeyTree(RegistryPath(id));} }
 public static void DataPermissions(string folder,string sid) { var user=new SecurityIdentifier(sid);foreach(string sub in new[]{"SCEN","CAMPAIGN"}){string p=Path.Combine(folder,sub);if(!Directory.Exists(p))continue;var acl=Directory.GetAccessControl(p);acl.AddAccessRule(new FileSystemAccessRule(user,FileSystemRights.Modify,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(p,acl);}foreach(string name in new[]{"PREFS.DAT","save.log","DDrawCompat-SF.log"}){string p=Path.Combine(folder,name);if(!File.Exists(p))File.WriteAllBytes(p,new byte[0]);var acl=File.GetAccessControl(p);acl.AddAccessRule(new FileSystemAccessRule(user,FileSystemRights.Modify,AccessControlType.Allow));File.SetAccessControl(p,acl);} }
}
